const SUB={text:'Text Box',callout:'Callout',cloudp:'Cloud+',pen:'Pen',hl:'Highlight',line:'Line',arrow:'Arrow',dim:'Dimension',poly:'Polyline',rect:'Rectangle',ell:'Ellipse',pgon:'Polygon',cloud:'Cloud',stamp:'Stamp',len:'Length Measurement',plen:'Polylength Measurement',area:'Area Measurement',rarea:'Area Measurement',perim:'Perimeter Measurement',count:'Count Measurement',cal:'Calibration',vp:'Viewport'};
