const SCALES=[['1/32"=1\'-0"',32],['1/16"=1\'-0"',16],['3/32"=1\'-0"',32/3],['1/8"=1\'-0"',8],['3/16"=1\'-0"',16/3],['1/4"=1\'-0"',4],['3/8"=1\'-0"',8/3],['1/2"=1\'-0"',2],['3/4"=1\'-0"',4/3],['1"=1\'-0"',1],['1 1/2"=1\'-0"',2/3],['3"=1\'-0"',1/3],['1"=10\'',1/10],['1"=20\'',1/20],['1"=30\'',1/30],['1"=40\'',1/40],['1"=50\'',1/50],['1"=100\'',1/100]];
