  {const hb=M.querySelector('#rvHl');if(hb)hb.onclick=()=>window.ameHyperlink&&window.ameHyperlink.open(null)}M.querySelector('#rvAdd').onchange=async e=>{const F=[...e.target.files];let last=null;for(const f of F){toast('Uploading '+f.name+'…');try{const id='r'+uid();const path='revu/'+id+'_'+f.name.replace(/[^\w.\-]+/g,'_');const fs=await window.claude.use('files');await fs.save(path,f);BLOB[path]=f;const d={name:f.name,path,size:f.size,marks:{},sc:{},by:me(),at:new Date().toISOString()};await db.doc('revu/'+id).set(d);last={...d,_id:id}}catch(x){toast('Upload failed: '+(x.message||x))}}if(last)open(last)};
