  const lbl=(x,y,t,size)=>t?`<text x="${x}" y="${y}" class="rvlbl" style="fill:${c};font-size:${(size||12)/Math.max(.4,Math.min(1,z))}px">${esc(t)}</text>`:'';let g='';const pts=Pt.map(p=>p.join(',')).join(' ');const[a,b]=[Pt[0],Pt[1]||Pt[0]];
