  if(m.t==='pen'||m.t==='hl')g=`<polyline points="${pts}" fill="none" stroke="${m.t==='hl'?'#f2cc60':c}" stroke-opacity="${m.t==='hl'?.4:op}" stroke-width="${m.t==='hl'?14:sw}" stroke-linecap="round" stroke-linejoin="round"/>`;
