    if(m.t==='cloudp'){const c2=m.c2||[a,[a[0]+60,a[1]+40]];g+=`<path d="${cloudPath(c2[0][0],c2[0][1],c2[1][0],c2[1][1],8)}" fill="none" ${stroke}/>`}
